function calcHPP(produk, bahanList) {
  return (produk.bahan||[]).reduce((s,b)=>{const x=bahanList.find(i=>i.id===b.id);return s+(x?x.harga*b.qty:0);},0);
}
function calcMargin(hj,hpp){return hj?((hj-hpp)/hj)*100:0;}
function suggestPrice(hpp,tm){return Math.ceil(hpp/(1-tm/100)/500)*500;}
function MarginBadge({margin,target}){
  const ok=margin>=target,warn=margin>=target*0.75;
  const c=ok?"#15803d":warn?"#d97706":"#dc2626",bg=ok?"#dcfce7":warn?"#fef3c7":"#fee2e2";
  return <span style={{background:bg,color:c,fontSize:11,fontWeight:700,padding:"2px 8px",borderRadius:99}}>{ok?"✓ ":"↓ "}{margin.toFixed(1)}%</span>;
}

